"""Generate docs/ECONOMICS_MODEL.md and docs/BEACON_BENCH_PLAN.md from the code, so the numbers cannot drift.

Usage: python tools/generate_model_docs.py [campaign_dir]
"""
import dataclasses
import math
import sys
from dataclasses import replace
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from rpo_project import bench, economics as eco  # noqa: E402

campaign = Path(sys.argv[1]) if len(sys.argv) > 1 else ROOT / "results" / "v4_1_validation"
S = eco.load_main_summary(campaign / "summary_main.csv")
A = eco.EconAssumptions()
M = lambda x: f"{x/1e6:,.2f}"          # EUR -> M EUR
pct = lambda x: f"{100*x:.1f}%"
inf = lambda x: "never" if math.isinf(x) else (">100% (not repaid)" if x > 1 else f"{100*x:.2f}%")
NAMES = {"C0_unprepared": "C0 unprepared", "C1_fiducials": "C1 fiducials", "C2_beacon": "C2 beacon (rate)", "C3_ios_mode": "C3 IOS mode"}


def econ_doc() -> str:
    o = ["# Economics model — preparation tiers and servicer throughput", "",
         f"**Generated by** `tools/generate_model_docs.py` from `{campaign.name}` (model `Phase2-RPO-MC-v4.1`). Re-run after any new campaign or assumption change.", "",
         "> **Read this first.** Every money, mass, price and probability input in section 1 is an **ASSUMPTION** made to give the proposal a calculable first-pass economics. None is a ClearSpace figure, a vendor quote or customer data. "
         "What is *calculated from the simulator* is: per-attempt outcome probabilities, delta-v, propellant, and the beacon mass. Results are expected values under these inputs, not forecasts. "
         "This implements Guide §16's design-for-value rule (discounted incremental benefit vs interface mass, integration and servicing price) for one GEO client; ECON-01 is **partly** addressed — real costs, downtime and risk remain open.", "",
         "## 1. Assumptions (all editable in `EconAssumptions`)", "", "| Parameter | Value | Basis |", "|:--|--:|:--|"]
    basis = {"client_annual_revenue_eur": "ASSUMED, high-value GEO comsat", "contribution_margin": "ASSUMED", "extension_years": "ASSUMED",
             "service_year": "ASSUMED rescue at year 10 of ~15", "discount_rate": "ASSUMED", "servicing_price_eur": "ASSUMED",
             "p_needs_rescue": "ASSUMED; the main driver, see section 5", "max_attempts": "ASSUMED operations policy",
             "p_collision_given_incomplete_retreat": "ASSUMED", "servicer_loss_eur": "ASSUMED"}
    for f in dataclasses.fields(A):
        v = getattr(A, f.name)
        shown = f"{v:,.2f}" if isinstance(v, float) and abs(v) < 1000 else f"{v:,.0f}"
        o.append(f"| `{f.name}` | {shown} | {basis.get(f.name, 'ASSUMED')} |")
    b = eco.evaluate_beacon_engineering_budget()
    o += ["", f"Beacon packaged mass **{b['packaged_unit_mass_g']:.0f} g** and nameplate **{b['recommended_nameplate_wh']:.1f} Wh** are *model-derived* (`ios.evaluate_beacon_engineering_budget`, itself built on assumed derating factors).", "",
          "## 2. What the simulator says per approach attempt (model-derived)", "",
          "| Tumble | Tier | Pass | Abort, retreat complete | Abort, retreat NOT complete | Keep-out violation |", "|--:|:--|--:|--:|--:|--:|"]
    for tum in (2.0, 3.0, 5.0):
        for t in eco.TIERS:
            x = eco.attempt_outcomes(S[(t, tum)])
            o.append(f"| {tum:g}°/s | {NAMES[t]} | {pct(x['pass'])} | {pct(x['abort_complete'])} | {pct(x['abort_incomplete'])} | {pct(x['unsafe'])} |")
    o += ["", "Retries are allowed only after a *complete* retreat. An incomplete retreat (estimate mismatch) or violation ends the mission and carries the assumed collision-cost risk. "
          "This uses the v4.1 retreat outcomes that the earlier retry plot had to mark `n/a`.", "",
          f"## 3. Servicing success within {A.max_attempts} attempts and expected value per client at 3°/s", "",
          f"Value of one successful rescue, net of the servicing price, discounted to launch: **€{M(eco.net_value_of_success(A))} M**. Expected value = P(needs rescue) × (P(success) × value − collision risk cost) − add-on cost.", "",
          "| Tier | P(success) | P(mission lost) | Expected attempts | Benefit €M | Add-on cost €M | Net €M |", "|:--|--:|--:|--:|--:|--:|--:|"]
    for t in eco.TIERS:
        e = eco.expected_value(t, S[(t, 3.0)], A)
        o.append(f"| {NAMES[t]} | {pct(e['p_success'])} | {pct(e['p_incomplete_or_unsafe'])} | {e['expected_attempts']:.2f} | {M(e['benefit_eur'])} | {M(e['addon_cost_eur'])} | {M(e['net_eur'])} |")
    o += ["", "**Reading:** with retries, fiducials already recover most of the value at 3°/s; the beacon's extra benefit is small there, and IOS mode costs more than it returns unless a rescue is likely or the client tumbles faster. At 5°/s only C3 can be serviced at all (it assumes the client can damp itself). The beacon is likely **undervalued** here: its non-RPO benefits (identity, interface location, health flags, knowing the client state before committing a servicer) and the fully degraded case are not in the simulator, so they carry no value in this table.", "",
          "## 4. Break-even probability that a client ever needs rescue", "",
          "Smallest P(needs rescue) at which the extra tier cost is repaid by its extra expected benefit (lower is easier to justify).", "",
          "| Tumble | C1 vs C0 | C2 vs C1 | C3 vs C2 | C3 vs C0 |", "|--:|--:|--:|--:|--:|"]
    for tum in (2.0, 3.0, 5.0):
        r = [eco.breakeven_p_needs_rescue(t, base, S, tum, A) for t, base in
             (("C1_fiducials", "C0_unprepared"), ("C2_beacon", "C1_fiducials"), ("C3_ios_mode", "C2_beacon"), ("C3_ios_mode", "C0_unprepared"))]
        o.append(f"| {tum:g}°/s | " + " | ".join(inf(x) for x in r) + " |")
    o += ["", "## 5. Sensitivity: net value of C2 beacon over C1 fiducials at 3°/s (€M per client)", "",
          "| P(needs rescue) \\ servicing price | €25 M | €50 M | €75 M | €100 M |", "|--:|--:|--:|--:|--:|"]
    for p in (0.02, 0.05, 0.10, 0.20, 0.40):
        row = []
        for price in (25e6, 50e6, 75e6, 100e6):
            a = replace(A, p_needs_rescue=p, servicing_price_eur=price)
            d = eco.expected_value("C2_beacon", S[("C2_beacon", 3.0)], a)["net_eur"] - eco.expected_value("C1_fiducials", S[("C1_fiducials", 3.0)], a)["net_eur"]
            row.append(M(d))
        o.append(f"| {pct(p)} | " + " | ".join(row) + " |")
    o += ["", "## 6. Servicer throughput (finite resources, Guide §16)", "",
          f"Servicer {A.servicer_wet_kg:.0f} kg wet, {A.servicer_prop_usable_kg:.0f} kg usable propellant, Isp {A.servicer_isp_s:.0f} s, {A.transfer_dv_mps:.0f} m/s per GEO transfer, {A.visit_duration_days:.0f} days per visit, {A.servicer_life_years:.0f}-year life. Propellant by Δv = Isp·g0·ln(m₀/m₁). "
          "Break-even price = (capex + operations) ÷ expected successful services. Only fuel and time limits are modelled; delivered refuel inventory, POD cargo and risk reserve are not.", "",
          "| Tumble | Tier | Propellant per visit kg | Visits (fuel/time limit) | Expected successful services | Break-even price per success €M |", "|--:|:--|--:|--:|--:|--:|"]
    for tum in (3.0, 5.0):
        for t in eco.TIERS:
            h = eco.servicer_throughput(t, S[(t, tum)], A)
            be = "n/a (no success)" if math.isinf(h["breakeven_price_per_success_eur"]) else M(h["breakeven_price_per_success_eur"])
            o.append(f"| {tum:g}°/s | {NAMES[t]} | {h['prop_per_visit_kg']:.1f} | {h['visits']} ({h['limit']}) | {h['expected_successful_services']:.1f} | {be} |")
    o += ["", "## 7. Product-family tiers from the ClearSpace deck (cumulative client-side cost, per unit)", "",
          "| Tier | Provisions | Unit €M | Mass kg | Launch €M | NRE share €M | Total €M |", "|:--|:--|--:|--:|--:|--:|--:|"]
    prov = {1: "capture fixture + fiducials", 2: "+ IOS mode + beacon", 3: "+ refuelling port", 4: "+ OSAN (power/data/POD)"}
    for n, nm in eco.PRODUCT_TIERS.items():
        c = eco.product_tier_cost(n, A)
        o.append(f"| {n} {nm} | {prov[n]} | {M(c['unit_eur'])} | {c['mass_kg']:.1f} | {M(c['launch_eur'])} | {M(c['nre_share_eur'])} | {M(c['total_eur'])} |")
    o += ["", "Tiers 3–4 have **no benefit model here** (refuel/POD value needs a fuel-price, lifetime-extension and POD-capability model); their cost is shown for the roadmap trade only.", "",
          "## 8. What this does and does not establish", "",
          "* Establishes a transparent calculation chain from simulator outcomes to € per client, and which inputs matter (P(needs rescue) and servicing price dominate).",
          "* Does **not** establish real prices, demand, insurance effects, downtime cost, or that clients would pay for preparation. Replace section-1 values with ClearSpace/operator data before any external claim.",
          "* Avoids double counting: benefit is the retained contribution of the extension net of the price paid; replacement-satellite avoidance is not added on top."]
    return "\n".join(o) + "\n"


def bench_doc() -> str:
    b = eco.evaluate_beacon_engineering_budget()
    o = ["# Service Beacon bench plan and virtual bench", "",
         f"**Generated by** `tools/generate_model_docs.py`. **No hardware exists.** Expected values come from the engineering model (`ios.evaluate_beacon_engineering_budget`, built on *assumed* derating, radio and battery figures); the virtual bench uses *assumed* component tolerances. "
         "It prepares milestone M3 (bench demonstration) and BEACON-01; it does not satisfy it.", "",
         "## 1. Survival sizing (Guide §15: E_usable ≥ P_avg × T_survival)", "",
         f"Guide worked example reproduced by `bench.average_power_w`: 0.01 W sleep + 1 % × 2 W TX + 10 % × 0.03 W sensing = **{bench.average_power_w(0.01,0.01,2.0,0.10,0.03):.3f} W**, 30 days = **{bench.required_nameplate_wh(0.033,30,1.0,1.0):.2f} Wh** ideal. "
         f"The model beacon (1 Hz, 15 ms TX) draws **{b['net_avg_power_mw']:.1f} mW**; derated nameplate for 30 days is **{b['recommended_nameplate_wh']:.1f} Wh** (derating {b['combined_derating_factor']:.2f}: converter, isolation, −20 °C, 15-year aging, depth of discharge, +20 % margin).", "",
         "| Survival days | Beacon rate Hz | Avg power mW | Ideal Wh | Nameplate Wh | Packaged mass g |", "|--:|--:|--:|--:|--:|--:|"]
    for r in bench.survival_sweep():
        o.append(f"| {r['survival_days']} | {r['rate_hz']:g} | {r['avg_power_mw']:.1f} | {r['ideal_wh']:.1f} | {r['nameplate_wh']:.1f} | {r['packaged_mass_g']:.0f} |")
    w = bench.wake_mode_trade()
    o += ["", "## 2. Periodic pulses vs wake-on-command (30 days)", "", "| Mode | Avg power mW | Energy Wh | Time to first data s | Note |", "|:--|--:|--:|--:|:--|"]
    for k, v in w.items():
        o.append(f"| {k} | {v['avg_mw']:.1f} | {v['energy_wh']:.1f} | {v['first_data_latency_s']:.0f} | {v['note']} |")
    o += ["", "Wake-on-command saves energy (assumes 18 mW receiver at 2 % duty and 10 minutes of interrogation per day) but depends on the servicer finding and interrogating the client, and adds an authentication surface. Periodic pulses are the safer default for a client that may be tumbling and silent.", "",
          "## 3. Antenna coverage under tumble", "",
          "For a randomly oriented client with two opposite patch antennas of half-beamwidth θ, P(servicer inside a cone) = 2 × (1 − cos θ) / 2. Packets needed for ≥ 1 reception at 95 % confidence:", "",
          "| Patch half-angle | P(cover) | Packets at 0 % loss | At 50 % loss | At 75 % loss |", "|--:|--:|--:|--:|--:|"]
    for ang in (45, 60, 75, 90):
        c = bench.coverage_probability(ang, 2)
        o.append(f"| {ang}° | {c:.2f} | " + " | ".join(str(bench.packets_for_confidence(c, l)) for l in (0.0, 0.5, 0.75)) + " |")
    o += ["", "At 1 Hz a 45° patch pair needs about 9 packets (9 s) with no loss and about 40 s at 75 % loss, so first contact is not the binding constraint; rate quality is. Packets are treated as independent; real patterns, body blockage and the correlation of orientation between consecutive packets are not modelled.", "",
          "## 4. Bench tests (expected values and pass limits from the model)", "", "| ID | Test | Measure | Expected | Pass limit | Procedure |", "|:--|:--|:--|--:|--:|:--|"]
    for t in bench.bench_tests():
        cmp = "≤" if t.direction == "max" else "≥"
        o.append(f"| {t.id} | {t.name} | {t.measure} | {t.expected:.1f} {t.unit} | {cmp} {t.limit:.1f} {t.unit} | {t.procedure} |")
    o += ["", "Record measured values and call `bench.evaluate_bench({'B1': ..., ...})` to get PASS / FAIL / NOT_RUN per test.", "",
          "## 5. Virtual bench (20,000 sampled builds)", "",
          "Component spreads are assumptions: sleep power ±25 % (1σ lognormal), TX power ±12 %, leakage ±50 %, RF output ±0.8 dB, link ±2.5 dB, cold capacity factor 0.85 ± 0.04, latency jitter 50 ± 40 ms.", "",
          "| ID | Test | P(pass) | 5th pct | 95th pct |", "|:--|:--|--:|--:|--:|"]
    for k, v in bench.virtual_bench().items():
        o.append(f"| {k} | {v['name']} | {pct(v['p_pass'])} | {v['p5']:.1f} | {v['p95']:.1f} |")
    o += ["", "B1 is the tightest (limit is only 25 % above the model average); a design review should either tighten sleep-current control or widen the energy margin. B7 (spoof rejection) is a logic test, not statistical: any acceptance is a fail.", "",
          "## 6. Indicative bench cost (ASSUMED)", "",
          "| Item | € |", "|:--|--:|", "| Engineering-model beacon (2 units) | 120,000 |", "| Thermal chamber time, 5 days | 15,000 |", "| RF test (analyser, attenuators, calibration) | 25,000 |", "| Engineering effort, ~3 person-months | 45,000 |", "| **Total** | **205,000** |", "",
          "Replace with quotes. Not a claim about hardware readiness."]
    return "\n".join(o) + "\n"


(ROOT / "docs" / "ECONOMICS_MODEL.md").write_text(econ_doc())
(ROOT / "docs" / "BEACON_BENCH_PLAN.md").write_text(bench_doc())
print("wrote docs/ECONOMICS_MODEL.md and docs/BEACON_BENCH_PLAN.md")
